INSERT INTO Fragrance (Fragrance_Name, Strength, Size, Notes, Price, Perfumer_ID, Brand_ID) SELECT 'Sauvage Eau de Toilette', 'Eau de Toilette', 50, 'Price in USD; captured 2026-09-21', 105.00, (SELECT Person_ID FROM Person WHERE First_Name='François' AND Last_Name='Demachy' ORDER BY Person_ID LIMIT 1), Brand_ID FROM Brand WHERE Name='Dior' AND NOT EXISTS (SELECT 1 FROM Fragrance f JOIN Brand b ON b.Brand_ID=f.Brand_ID WHERE b.Name='Dior' AND f.Fragrance_Name='Sauvage Eau de Toilette' AND f.Strength='Eau de Toilette' AND f.Size=50);
INSERT INTO Fragrance_Has_Note (Fragrance_ID, Note_ID, Notes) SELECT f.Fragrance_ID, n.Note_ID, NULL FROM Fragrance f JOIN Brand b ON b.Brand_ID=f.Brand_ID JOIN Fragrance_Note n ON n.Note_Name='Bergamot' WHERE b.Name='Dior' AND f.Fragrance_Name='Sauvage Eau de Toilette' AND f.Strength='Eau de Toilette' AND f.Size=50;
